:root[data-theme="dark"] {
  --bg: #1c1a18; --panel: #262320; --ink: #ece7df; --muted: #a39b8f; --line: #3b3732; --btn: #34302b; --btn-on: #ece7df; --btn-on-ink: #1c1a18; color-scheme: dark; }
html, body { height: 100%; }
body { margin: 0; background: var(--bg); color: var(--ink); font-family: var(--font); font-size: 14px; }
.app { height: 100%; display: flex; flex-direction: column; box-sizing: border-box; padding-inline: 12px; padding-block: 8px; gap: 8px; min-height: 0; }
header { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
h1 { font-size: 15px; font-weight: 600; margin: 0; letter-spacing: .02em; }
h1 small { font-weight: 400; color: var(--muted); margin-left: 6px; }
.row { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; min-width: 0; }
button, select, input[type=text] { font: inherit; color: var(--ink); }
button { background: var(--btn); border: 1px solid var(--line); border-radius: 6px; padding: 5px 9px; cursor: pointer; line-height: 1.2; }
button:hover { border-color: var(--muted); }
button[aria-pressed="true"], button.on { background: var(--btn-on); color: var(--btn-on-ink); border-color: var(--btn-on); }
button:focus-visible, select:focus-visible, input:focus-visible { outline: 2px solid var(--portal); outline-offset: 1px; }
kbd { font-family: var(--mono); font-size: 10px; opacity: .65; margin-left: 4px; }
select { background: var(--btn); border: 1px solid var(--line); border-radius: 6px; padding: 5px 6px; }
label.chk { display: inline-flex; gap: 4px; align-items: center; color: var(--muted); white-space: nowrap; }
.main { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 10px; }
.stage { position: relative; min-height: 0; border: 1px solid var(--line); border-radius: 6px; overflow: hidden; background: var(--paper); }
svg#cv { width: 100%; height: 100%; display: block; touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
svg#cv.draw { cursor: crosshair; }
.hud { position: absolute; left: 8px; bottom: 8px; right: 8px; display: flex; flex-direction: column; gap: 6px; pointer-events: none; }
.hud > * { pointer-events: auto; }
.status { align-self: flex-start; background: color-mix(in srgb, var(--bg) 88%, transparent); border: 1px solid var(--line); border-radius: 6px; padding: 3px 8px; font-family: var(--mono); font-size: 11px; color: var(--muted); max-width: 100%; }
.composer { display: flex; gap: 6px; align-items: center; background: var(--bg); border: 1px solid var(--mark); border-radius: 8px; padding: 6px; }
.composer[hidden] { display: none; }
.composer input { flex: 1; min-width: 0; background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 6px 8px; }
.chip { font-family: var(--mono); font-size: 10px; text-transform: uppercase; letter-spacing: .06em; padding: 2px 6px; border-radius: 4px; background: var(--mark); color: #fff; white-space: nowrap; }
.zoom { position: absolute; right: 8px; top: 8px; display: flex; flex-direction: column; gap: 4px; }
.zoom button { width: 30px; padding: 4px 0; }
aside { min-height: 0; display: flex; flex-direction: column; gap: 8px; background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 10px; }
aside h2 { margin: 0; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); display: flex; justify-content: space-between; }
#log { list-style: none; margin: 0; padding: 0; overflow: auto; flex: 1; min-height: 80px; display: flex; flex-direction: column; gap: 6px; }
#log li { border: 1px solid var(--line); border-radius: 6px; padding: 6px 8px; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 2px 8px; align-items: center; cursor: pointer; background: var(--bg); }
#log li.sel { border-color: var(--mark); }
#log li.done { opacity: .55; }
#log li.done .chip { background: var(--muted); }
#log .t { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#log .m { grid-column: 2 / 4; font-family: var(--mono); font-size: 10.5px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#log .x { padding: 1px 6px; }
.empty { color: var(--muted); font-size: 13px; line-height: 1.45; }
.banner { background: var(--panel); border: 1px solid var(--exit); color: var(--ink); border-radius: 6px; padding: 6px 10px; font-size: 12px; }
.banner[hidden] { display: none; }
.legend { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11px; color: var(--muted); }
.legend i { display: inline-block; width: 14px; height: 0; border-top: 2px solid; vertical-align: middle; margin-right: 4px; }
@media (max-width: 860px) {
  .app { height: auto; min-height: 100%; }
  .main { grid-template-columns: minmax(0, 1fr); }
  .stage { height: 64vh; min-height: 360px; }
  aside { min-height: 240px; }
}
.sty { position: relative; } .sty summary { cursor: pointer; background: var(--btn); border: 1px solid var(--line); border-radius: 6px; padding: 5px 9px; list-style: none; }
.stybox { position: absolute; z-index: 20; top: 34px; left: 0; width: 230px; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 10px; display: grid; gap: 8px; box-shadow: 0 6px 20px rgba(0,0,0,.18); }
.stybox label { display: flex; justify-content: space-between; align-items: center; gap: 8px; color: var(--ink); font-size: 12px; }
.stybox input[type=range] { width: 110px; } .stybox input[type=color] { width: 38px; height: 24px; padding: 0; border: 1px solid var(--line); background: none; }
.tabs { display: flex; gap: 4px; } .tabs button { padding: 3px 8px; font-size: 11px; text-transform: uppercase; letter-spacing: .06em; } .tabs b { font-weight: 600; opacity: .7; }
#spane { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 6px; } #spane[hidden] { display: none; } #log[hidden] { display: none; }
.sfilter { display: flex; flex-wrap: wrap; gap: 4px; } .sfilter button { padding: 2px 7px; font-size: 11px; }
#slog { list-style: none; margin: 0; padding: 0; overflow: auto; flex: 1; min-height: 80px; display: flex; flex-direction: column; gap: 5px; }
#slog li { border: 1px solid var(--line); border-radius: 6px; padding: 5px 8px; display: grid; grid-template-columns: auto minmax(0,1fr); gap: 2px 8px; cursor: pointer; background: var(--bg); font-size: 12px; }
#slog li.sel { border-color: #7a3fd1; } #slog li.acc { border-left: 4px solid #1a8f3c; } #slog li.rej { opacity: .5; border-left: 4px solid #999; } #slog li.rej .st { text-decoration: line-through; }
#slog .n { font-family: var(--mono); font-size: 10.5px; background: #7a3fd1; color: #fff; border-radius: 4px; padding: 1px 5px; align-self: start; }
#slog li.acc .n { background: #1a8f3c; } #slog li.rej .n { background: #999; }
#slog .c { grid-column: 2; font-family: var(--mono); font-size: 10px; color: var(--muted); }
#sdet { border: 1px solid #7a3fd1; border-radius: 8px; padding: 8px; font-size: 12px; display: grid; gap: 6px; background: var(--bg); max-height: 46%; overflow: auto; }
#sdet[hidden] { display: none; } #sdet h3 { margin: 0; font-size: 13px; } #sdet p { margin: 0; line-height: 1.4; } #sdet .why { color: var(--muted); } #sdet .row { display: flex; gap: 6px; }
#sdet .acc { background: #1a8f3c; color: #fff; border-color: #1a8f3c; } #sdet .rej { background: #8a8a8a; color: #fff; border-color: #8a8a8a; }
#slog li.sol { border-left: 4px solid #1f6fd1; } #slog li.sol .n { background: #1f6fd1; } #slog li.part { border-left: 4px solid #d98a00; } #slog li.part .n { background: #d98a00; }
</style>

<div class="app">
  <header>
    <h1>EG Redline<small>mark on the plan, Claude reads the marks</small></h1>
    <div class="row">
      <select id="area" aria-label="Jump to area"></select>
      <label class="chk"><input type="checkbox" id="l-img" checked>Lageplan</label>
      <label class="chk"><input type="checkbox" id="l-zones" checked>Zones</label>
      <label class="chk"><input type="checkbox" id="l-ids" checked>Ids</label>
      <label class="chk"><input type="checkbox" id="l-grid" checked>Grid</label>
      <details class="sty"><summary>Style</summary><div class="stybox">
        <label>Lageplan<input type="range" id="img-op" min="10" max="100" value="45"></label>
        <label>Fill strength<input type="range" id="st-fill" min="30" max="150" value="100"></label>
        <label>Outlines<input type="range" id="st-line" min="40" max="300" value="100"></label>
        <label>Outline colour<input type="color" id="st-oc"></label>
        <label>Grey Lageplan<input type="checkbox" id="st-grey"></label>
        <label>Circulation<input type="color" id="st-circ"></label>
        <label>Vertical (stairs, lifts)<input type="color" id="st-vert"></label>
        <label>Crossable rooms<input type="color" id="st-xroom"></label>
        <label>Other rooms<input type="color" id="st-room"></label>
        <button id="st-reset" type="button">Reset</button>
      </div></details>
      <label class="chk"><input type="checkbox" id="snap" checked>Snap</label>
      <label class="chk"><input type="checkbox" id="l-applied">Applied marks</label>
      <label class="chk"><input type="checkbox" id="l-sugg" checked>Suggestions</label>
    </div>
  </header>
  <div class="row" id="tools" role="toolbar" aria-label="Tools"></div>
  <div class="banner" id="banner" hidden></div>
  <div class="main">
    <div class="stage">
      <svg id="cv" aria-label="Floor plan"></svg>
      <div class="zoom"><button id="zin" aria-label="Zoom in">+</button><button id="zout" aria-label="Zoom out">&minus;</button><button id="zfit" aria-label="Fit" style="font-size:11px">fit</button></div>
      <div class="hud">
        <div class="composer" id="composer" hidden>
          <span class="chip" id="c-kind">note</span><span id="c-target" style="font-family:var(--mono);font-size:11px;color:var(--muted);max-width:30%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"></span>
          <input type="text" id="c-text" autocomplete="off">
          <button id="c-done">Done</button>
          <button id="c-del">Delete</button>
        </div>
        <div class="status" id="status"></div>
      </div>
    </div>
    <aside>
      <h2><span class="tabs"><button id="tab-m" class="on" type="button">Marks <b id="count">0</b></button><button id="tab-s" type="button">Suggestions <b id="scount">0</b></button></span></h2>
      <ul id="log"></ul>
      <div id="spane" hidden>
        <div class="sfilter" id="sfilter"></div>
        <ul id="slog"></ul>
        <div id="sdet" hidden></div>
      </div>
      <div class="legend">
        <span><i style="border-color:var(--portal)"></i>door</span>
        <span><i style="border-color:var(--portal);border-top-style:dashed"></i>virtual</span>
        <span><i style="border-color:var(--exit)"></i>exit</span>
        <span><i style="border-color:var(--mark)"></i>your mark</span>
      </div>
    </aside>
  </div>
</div>

